#if UNITY_EDITOR
using System;
using System.Linq;
using Hadal.Gameplay.Art;
using UnityEditor;
using UnityEngine;

namespace Hadal.EditorTools
{
    /// <summary>
    /// Import rules for FBX files generated by art/blender (Assets/_Hadal/Art/):
    /// <list type="bullet">
    /// <item>Buildings and props (generate.py): HAD_* materials map to the palette, ANIM_* parts get an <see cref="ArtAnimator"/>.</item>
    /// <item>Characters (characters.py): generic rig with named clips (locomotion and idles loop),
    /// URP Lit material on the point-filtered palette atlas.</item>
    /// </list>
    /// </summary>
    public sealed class HadalArtImporter : AssetPostprocessor
    {
        private const string ArtRoot = "Assets/_Hadal/Art/";
        public const string CharactersRoot = ArtRoot + "Characters/";

        /// <summary>Clips that cycle; everything else (Wave, Death, HitReact...) plays once.</summary>
        public static readonly string[] LoopingClips =
        {
            "Idle", "Walk", "Run", "Idle_Gun", "Walk_Gun", "Run_Gun_Shoot", "Flying_Idle", "Fast_Flying", "Dance"
        };

        private static bool IsFbx(string path) => path.EndsWith(".fbx", StringComparison.OrdinalIgnoreCase);
        private static bool IsCharacter(string path) => path.StartsWith(CharactersRoot) && IsFbx(path);
        private static bool IsHadalArt(string path) => path.StartsWith(ArtRoot) && IsFbx(path) && !IsCharacter(path);

        /// <summary>"crew_engineer|Walk" (Blender take name) -> "Walk".</summary>
        public static string ClipName(string take)
        {
            var bar = take.LastIndexOf('|');
            return bar >= 0 ? take.Substring(bar + 1) : take;
        }

        private void OnPreprocessModel()
        {
            if (IsCharacter(assetPath))
            {
                PreprocessCharacter((ModelImporter)assetImporter);
                return;
            }

            if (!IsHadalArt(assetPath))
                return;

            var importer = (ModelImporter)assetImporter;
            importer.globalScale = 1f;
            importer.useFileScale = true;
            importer.importCameras = false;
            importer.importLights = false;
            importer.importAnimation = false;
            importer.animationType = ModelImporterAnimationType.None;
            importer.isReadable = false;
            importer.meshCompression = ModelImporterMeshCompression.Medium;
            importer.importNormals = ModelImporterNormals.Import;
            importer.materialImportMode = ModelImporterMaterialImportMode.ImportStandard;
            importer.materialLocation = ModelImporterMaterialLocation.InPrefab;

            foreach (var name in HadalArtPalette.Names)
            {
                var material = HadalArtPalette.Load(name);
                if (material == null)
                    continue;

                importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material), HadalArtPalette.Prefix + name), material);
            }
        }

        private static void PreprocessCharacter(ModelImporter importer)
        {
            importer.globalScale = 1f;
            importer.useFileScale = true;
            importer.importCameras = false;
            importer.importLights = false;
            importer.isReadable = false;
            importer.meshCompression = ModelImporterMeshCompression.Medium;
            importer.importNormals = ModelImporterNormals.Import;
            importer.materialImportMode = ModelImporterMaterialImportMode.ImportStandard;
            importer.materialLocation = ModelImporterMaterialLocation.InPrefab;
            importer.materialSearch = ModelImporterMaterialSearch.Local;
            importer.animationType = ModelImporterAnimationType.Generic;
            importer.avatarSetup = ModelImporterAvatarSetup.CreateFromThisModel;
            importer.importAnimation = true;
            importer.animationCompression = ModelImporterAnimationCompression.Optimal;
            importer.optimizeGameObjects = true;
        }

        private void OnPreprocessAnimation()
        {
            if (!IsCharacter(assetPath))
                return;

            var importer = (ModelImporter)assetImporter;
            var clips = importer.defaultClipAnimations;
            foreach (var clip in clips)
            {
                clip.name = ClipName(clip.takeName);
                clip.loopTime = LoopingClips.Contains(clip.name);
                // Root stays put: crew movement is driven by gameplay code, not animation.
                clip.lockRootPositionXZ = true;
                clip.lockRootHeightY = true;
                clip.lockRootRotation = true;
                clip.keepOriginalPositionY = true;
            }

            importer.clipAnimations = clips;
        }

        private void OnPreprocessTexture()
        {
            if (!assetPath.StartsWith(CharactersRoot) || !assetPath.EndsWith("_atlas.png", StringComparison.OrdinalIgnoreCase))
                return;

            // Flat palette cells: point filtering and no mips keep neighbouring cells from bleeding.
            var importer = (TextureImporter)assetImporter;
            importer.filterMode = FilterMode.Point;
            importer.mipmapEnabled = false;
            importer.textureCompression = TextureImporterCompression.Uncompressed;
            importer.maxTextureSize = 512;
        }

        private void OnPostprocessMaterial(Material material)
        {
            if (!IsCharacter(assetPath))
                return;

            var texture = material.mainTexture;
            var shader = Shader.Find("Universal Render Pipeline/Lit");
            if (shader == null)
                return;

            material.shader = shader;
            if (texture != null)
                material.SetTexture("_BaseMap", texture);
            material.SetColor("_BaseColor", Color.white);
            material.SetFloat("_Metallic", 0f);
            material.SetFloat("_Smoothness", 0.25f);
            material.enableInstancing = true;
        }

        private void OnPostprocessModel(GameObject root)
        {
            if (!IsHadalArt(assetPath))
                return;

            foreach (var t in root.GetComponentsInChildren<Transform>(true))
            {
                if (!ArtAnimator.TryParse(t.name, out var mode, out var axis, out var speed))
                    continue;

                var animator = t.gameObject.AddComponent<ArtAnimator>();
                animator.Configure(mode, axis, speed);
            }
        }
    }
}
#endif
